#include "generator.h"
#include <ctype.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#ifdef _WIN32
#include <direct.h>
#define MKDIR(p) _mkdir(p)
#else
#include <sys/stat.h>
#define MKDIR(p) mkdir((p),0777)
#endif

static bool join(char*out,size_t n,const char*d,const char*f){int r=snprintf(out,n,"%s/%s",d,f);return r>0&&(size_t)r<n;}
static bool mkdirs(const char *dir){char b[2048];size_t n=strlen(dir);if(!n||n>=sizeof b)return false;memcpy(b,dir,n+1);for(size_t i=0;i<n;i++)if((b[i]=='/'||b[i]=='\\')&&i>0&&b[i-1]!=':'){char c=b[i];b[i]=0;if(MKDIR(b)!=0&&errno!=EEXIST)return false;b[i]=c;}return MKDIR(b)==0||errno==EEXIST;}
static const char *base(const char*p){const char*b=p;for(;*p;p++)if(*p=='/'||*p=='\\')b=p+1;return b;}
static bool safe_name(const char*s){if(!*s)return false;for(;*s;s++)if((unsigned char)*s<32||*s=='"'||*s=='\r'||*s=='\n')return false;return true;}
static void stem_token(const char*path,char*out,size_t cap){const char*b=base(path);size_t n=strlen(b);if(n>4&&b[n-4]=='.'&&(b[n-3]=='d'||b[n-3]=='D')&&(b[n-2]=='l'||b[n-2]=='L')&&(b[n-1]=='l'||b[n-1]=='L'))n-=4;size_t j=0;for(size_t i=0;i<n&&j+1<cap;i++){unsigned char c=(unsigned char)b[i];out[j++]=(char)(isalnum(c)||c=='_'?c:'_');}if(!j&&cap>1)out[j++]='x';out[j]=0;}
static bool selected(size_t i,const DpgImports*im,bool all){if(all)return true;for(size_t j=0;j<im->count;j++)if(im->items[j].matched&&im->items[j].export_index==i)return true;return false;}

bool generate_proxy(const char*dir,const char*dll,const DpgImports*im,const DpgExports*ex,bool all,char*err,size_t cap){
    if(!mkdirs(dir)){if(cap)snprintf(err,cap,"cannot create output directory %s: %s",dir,strerror(errno));return false;}
    char stem[256],realmod[300],realfile[320],proxyfile[320];stem_token(dll,stem,sizeof stem);snprintf(realmod,sizeof realmod,"%s_real",stem);snprintf(realfile,sizeof realfile,"%s.dll",realmod);snprintf(proxyfile,sizeof proxyfile,"%s.dll",stem);
    char p[2048];FILE*f;if(!join(p,sizeof p,dir,"proxy.def")||!(f=fopen(p,"wb")))goto io;fprintf(f,"LIBRARY \"%s\"\nEXPORTS\n",stem);
    size_t emitted=0;for(size_t i=0;i<ex->count;i++){const DpgExport*x=&ex->items[i];if(!selected(i,im,all))continue;if(x->has_name){if(!safe_name(x->name)){fclose(f);if(cap)snprintf(err,cap,"export name contains characters unsafe for .def output");return false;}fprintf(f,"  \"%s\"=%s.%s @%u\n",x->name,realmod,x->name,x->ordinal);}else fprintf(f,"  dpg_ordinal_%u=%s.#%u @%u NONAME\n",x->ordinal,realmod,x->ordinal,x->ordinal);emitted++;}
    if(!emitted){fclose(f);if(cap)snprintf(err,cap,"no matched exports are available for proxy generation");return false;}if(fclose(f)!=0)goto io;
    if(!join(p,sizeof p,dir,"proxy.c")||!(f=fopen(p,"wb")))goto io;
    fputs("/* Generated by DLLProxyGen. Forwarded exports are defined in proxy.def. */\n#include <windows.h>\n\n/* USER SETUP REGION: add explicit, externally-invoked initialization here later.\n   Do not perform file I/O, LoadLibrary, logging, or blocking work in DllMain. */\n\nBOOL WINAPI DllMain(HINSTANCE instance, DWORD reason, LPVOID reserved)\n{\n    (void)instance; (void)reason; (void)reserved;\n    return TRUE;\n}\n",f);if(fclose(f)!=0)goto io;
    if(!join(p,sizeof p,dir,"build.sh")||!(f=fopen(p,"wb")))goto io;
    fprintf(f,"#!/bin/sh\nset -eu\ngcc -std=c11 -Wall -Wextra -Wpedantic -Wconversion -O2 -shared -o '%s' proxy.c proxy.def\n",proxyfile);if(fclose(f)!=0)goto io;
    if(!join(p,sizeof p,dir,"README.txt")||!(f=fopen(p,"wb")))goto io;
    fprintf(f,"DLLProxyGen forwarding proxy\n============================\n\n1. Rename/copy the inspected original DLL to: %s\n2. Build the proxy in a MinGW-w64 shell:\n   gcc -std=c11 -Wall -Wextra -Wpedantic -Wconversion -O2 -shared -o %s proxy.c proxy.def\n3. Place %s and %s together in a controlled test directory.\n4. Inspect exports with: objdump -p %s\n\nThe forwarders target module '%s', never the proxy itself. Windows module\nresolution still applies; test in a clean directory and do not deploy automatically.\n\nNo function prototype was inferred or enabled. Forwarding does not require one.\nAn all-forwarder export does not run custom C before/after each call. DllMain must\nremain loader-lock safe. Dynamic/delay imports, data exports, special ABIs and typed\nhooks are not handled by this generated MVP.\n",realfile,proxyfile,proxyfile,realfile,proxyfile,realmod);if(fclose(f)!=0)goto io;
    return true;
io:if(cap)snprintf(err,cap,"cannot write %s: %s",p,strerror(errno));return false;
}
